import heapq
class Solution:
    def deleteGreatestValue(self, grid: List[List[int]]) -> int:
        heaps = [[-x for x in row] for row in grid]
        for h in heaps: heapq.heapify(h)
        ans = 0
        for _ in range(len(grid[0])):
            ans += max(-heapq.heappop(h) for h in heaps)
        return ans

