class Solution {
public:
    int deleteGreatestValue(vector<vector<int>>& grid) {
        vector<priority_queue<int>> heaps;
        for (auto& row : grid) heaps.emplace_back(less<int>(), row);
        int ans = 0;
        for (int j = 0; j < (int)grid[0].size(); j++) {
            int mx = 0;
            for (auto& h : heaps) { mx = max(mx, h.top()); h.pop(); }
            ans += mx;
        }
        return ans;
    }
};

